from typing import Optional

import typer

from typer.testing import CliRunner

runner = CliRunner()


def test_option_envvar_basic() -> None:
    app = typer.Typer()

    @app.command("opt")
    def from_option(user: str = typer.Option(envvar="MY_USER")):
        print(f"Hello {user}")

    result = runner.invoke(app, [], env={"MY_USER": "bar"})
    assert result.exit_code == 0, result.output
    assert "Hello bar" in result.stdout, result.stdout


def test_option_envvar_default() -> None:
    app = typer.Typer()

    @app.command("opt")
    def from_option(user: str = typer.Option("baz", envvar="MY_USER")):
        print(f"Hello {user}")

    result = runner.invoke(app, [], env={})
    assert result.exit_code == 0, result.output
    assert "Hello baz" in result.stdout, result.stdout


def test_option_envvar_required_multivalue() -> None:
    app = typer.Typer()

    @app.command("opt")
    def from_option(
        users: list[str] = typer.Option(..., envvar="MY_USERS"),
    ):
        print(f"Hello {users}")

    result = runner.invoke(app, [], env={"MY_USERS": "foo,bar"})
    assert result.exit_code == 0, result.output
    assert "Hello ['foo', 'bar']" in result.stdout, result.stdout


def test_option_envvar_cli_takes_precedence() -> None:
    app = typer.Typer()

    @app.command("opt")
    def from_option(user: str = typer.Option(envvar="MY_USER")):
        print(f"Hello {user}")

    result = runner.invoke(app, ["--user", "cli"], env={"MY_USER": "bar"})
    assert result.exit_code == 0, result.output
    assert "Hello cli" in result.stdout, result.stdout


def test_option_envvar_auto_prefix() -> None:
    app = typer.Typer(context_settings={"auto_envvar_prefix": "APP"})

    @app.command("opt")
    def from_option(user: str = typer.Option()):
        print(f"Hello {user}")

    result = runner.invoke(app, [], env={"APP_OPT_USER": "bar"})
    assert result.exit_code == 0, result.output
    assert "Hello bar" in result.stdout, result.stdout

